using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json.Nodes;
using DesktopCritters.Core;
namespace DesktopCritters;
public static class ModelTests {
 private static int checks;
 private static void Check(bool ok,string message){if(!ok)throw new Exception("FAIL: "+message);checks++;Console.WriteLine("PASS: "+message);}
 private static World Empty(int seed=4){var w=new World(1440,900,seed);w.Bugs.Clear();w.Eggs.Clear();w.Foods.Clear();w.Corpses.Clear();w.Splats.Clear();w.Serial=1000;w.InvasionTimer=10000;w.AutoFoodTimer=-10000;return w;}
 public static int Run(){try{checks=0;var w=new World(1440,900,8);Check(w.Count(Species.Roach)==8&&w.Count(Species.Ant)==32,"initial two-camp population");Check(w.Bugs.Any(b=>!b.Adult),"hatchlings and adults coexist");Check(w.Bugs.Select(b=>b.Id).Distinct().Count()==w.Bugs.Count,"initial individual identities unique");Check(w.Reserved(Species.Roach)<=60&&w.Reserved(Species.Ant)<=240,"initial breeding slots bounded");
  for(int n=0;n<30;n++)w.AddFood(new V(500,400));Check(w.Foods.Count==18,"food count bounded under repeated feeding");
  var feed=Empty();var ant=new Bug{Id=1,Species=Species.Ant,P=new V(400,400)};var roach=new Bug{Id=2,Species=Species.Roach,P=new V(800,400)};feed.Bugs.AddRange(new[]{ant,roach});feed.AddFood(new V(600,400),Snack.Pizza);var food=feed.Foods[0];int original=food.Portions;double size=feed.Scale(ant,false);feed.Bite(ant,food);Check(food.Portions<original&&ant.Meals==1&&ant.Bulk>0,"real bite consumes nutrition and grows the chosen individual");Check(feed.Scale(ant,false)>size*1.5,"one large bite produces visible ant growth");double once=ant.Bulk;feed.Bite(ant,food);Check(ant.Bulk==once&&ant.Meals==1,"bite cooldown prevents click-spam growth");
  for(int n=0;n<6;n++)foreach(var b in feed.Bugs){b.Cooldown=0;feed.Bite(b,food);}Check(feed.Bugs.All(b=>b.Bulk==1&&b.Morph==4),"both camps can reach their final giant form");Check(Math.Abs(feed.Scale(ant,false)*26/(feed.Scale(roach,false)*65)-.5)<.001,"largest ant body is half largest roach");Check(Math.Abs(130*78*Math.Pow(feed.Scale(roach,false),2)/((feed.Width-50)*(feed.Height-70))-.25)<.01,"largest roach envelope reaches quarter of work field");ant.ShownBulk=1;Check(feed.BodyHit(ant,ant.P+new V(feed.Scale(ant)*10,0)),"giant bodies have usable edge hit regions");
  var normal=Empty();var worker=new Bug{Id=1,Species=Species.Ant,P=new V(400,400)};normal.Bugs.Add(worker);normal.AddFood(worker.P,Snack.Cookie,1000);for(int n=0;n<15;n++){worker.Cooldown=0;normal.Bite(worker,normal.Foods[0]);}Check(worker.Bulk==.3,"ordinary food preserves ordinary-size adults");Check(normal.SnackScale(Snack.Pizza)>5&&normal.SnackScale(Snack.Cookie)==1,"giant food uses viewport-scaled size");
  var mix=Empty();for(int n=0;n<100;n++)mix.Bugs.Add(new Bug{Id=n,Species=n<40?Species.Roach:Species.Ant,P=new V(500,400)});mix.AddFood(new V(500,400),Snack.Pizza,1000000);foreach(var b in mix.Bugs)for(int n=0;n<6;n++){b.Cooldown=0;mix.Bite(b,mix.Foods[0]);}Check(mix.Bugs.Count(b=>b.Bulk>=.78)==2,"unlimited giant food still allows one final giant per camp");Check(mix.Bugs.Count(b=>b.Bulk<=.3)>=80,"at least eighty percent remain normal size");var leader=mix.Bugs.First(b=>b.Species==Species.Ant&&b.Bulk>=.78);mix.Kill(leader,false);var heir=mix.Bugs.First(b=>b.Species==Species.Ant&&b.Bulk>.3);heir.Cooldown=0;mix.Bite(heir,mix.Foods[0]);Check(heir.Bulk>=.78,"a surviving adult can replace a fallen giant");var stages=new HashSet<int>();var specimen=new Bug();foreach(var s in new[]{(.1,0d),(.6,0d),(1d,.1),(1d,.5),(1d,1d)}){specimen.Growth=s.Item1;specimen.Bulk=s.Item2;stages.Add(specimen.Morph);}Check(stages.SetEquals(Enumerable.Range(0,5)),"five growth stages remain distinct");
  var hatch=Empty();hatch.Eggs.Add(new Egg{Id=500,Species=Species.Roach,P=new V(500,400),HatchTime=1,Brood=3});hatch.RoachFood=0;hatch.AntFood=0;for(int n=0;n<65;n++)hatch.Life(.05);Check(hatch.Bugs.Count==3&&hatch.Eggs.Count==0,"one prepaid roach egg case hatches three young");Check(hatch.Bugs.All(b=>b.Growth<1&&b.Generation==2),"offspring remain small and carry a new generation");Check(hatch.Bugs.Select(b=>b.Id).Distinct().Count()==3,"hatching allocates unique IDs");var young=hatch.Bugs[0];double growth=young.Growth;for(int n=0;n<600;n++)hatch.Life(.05);Check(young.Growth==growth,"starvation stops juvenile growth");hatch.RoachFood=100;for(int n=0;n<1400;n++)hatch.Life(.05);Check(hatch.Grown>0&&young.Adult,"feeding stock permits maturation");
  var fertile=new World(1280,800,81);fertile.SetRelation(Relation.Trade,"test");for(int n=0;n<2200;n++)fertile.Update(.05);Check(fertile.Hatched>0&&fertile.Bugs.Any(b=>b.Generation>1),"autonomous reproduction creates descendants");Check(fertile.Reserved(Species.Roach)<=60&&fertile.Reserved(Species.Ant)<=240,"live plus unhatched population stays bounded");Check(fertile.Bugs.Select(b=>b.Id).Concat(fertile.Eggs.Select(e=>e.Id)).Distinct().Count()==fertile.Bugs.Count+fertile.Eggs.Count,"identity uniqueness survives reproduction");
  var full=Empty();for(int n=0;n<60;n++)full.Bugs.Add(new Bug{Id=n,Species=Species.Roach,P=new V(400,400)});Check(!full.PlaceEgg(Species.Roach,new V(500,400)),"manual eggs cannot bypass population budget");var laying=Empty();laying.Paused=true;laying.Interactive=true;laying.Tool=Tool.RoachEgg;laying.Press(new V(500,400));Check(laying.Eggs.Count==1,"eggs can be placed while paused");double age=laying.Eggs[0].Age;laying.Update(.05);Check(laying.Eggs[0].Age==age,"pause freezes egg incubation");
  var dead=Empty();var victim=new Bug{Id=1,Species=Species.Roach,P=new V(600,450)};dead.Bugs.Add(victim);dead.Swat(victim.P);Check(dead.Bugs.Count==0&&dead.Corpses.Count==1,"slipper kills rather than temporarily stunning");Check(dead.Splats.Count==1&&dead.Splats[0].Drops.Count>=32,"dead roach releases many liquid droplets");dead.SlapAge=1;dead.Swat(victim.P);Check(dead.Splats.Count==1,"repeated swatting of corpse never creates duplicate splashes");dead.Paused=true;dead.Update(.05);Check(dead.Splats[0].Age==0,"pause freezes liquid flight");dead.Paused=false;for(int n=0;n<40;n++)dead.Update(.05);Check(dead.Splats[0].Age>1,"liquid remains after flight completes");var loaded=Empty();loaded.Restore(dead.SaveJson());Check(loaded.Corpses.Count==1&&loaded.Splats.Count==1,"dead roach and liquid survive save round-trip");Check(loaded.Splats[0].Age>=1,"save reload does not replay death explosion");loaded.SweepAt(victim.P);Check(loaded.Corpses.Count==0&&loaded.Splats.Count==0&&loaded.Sweeps[^1].Stains.Count==1,"broom removes corpse and wet stain together");
  var giant=new Bug{Id=3,Species=Species.Roach,P=new V(900,450),Bulk=1,ShownBulk=1};dead.Spill(giant,true);Check(dead.Splats[^1].Radius>dead.Splats[0].Radius*2,"giant death produces a larger splash");var stain=dead.Splats[^1];var spot=stain.Drops.OrderByDescending(d=>d.Offset.Length).First().Offset;var far=stain.P+new V(spot.X*Math.Cos(stain.Angle)-spot.Y*Math.Sin(stain.Angle),spot.X*Math.Sin(stain.Angle)+spot.Y*Math.Cos(stain.Angle));Check(stain.Hit(far,1),"outer landing drops can be selected for cleaning");dead.SweepAt(far);Check(!dead.Splats.Any(s=>s.BugId==3),"broom clears the full outer splash");
  var missed=Empty();missed.Swat(new V(500,400));Check(missed.Splats.Count==0,"missed slap creates no fake juice");missed.SlapAge=1;missed.Bugs.Add(new Bug{Id=1,Species=Species.Ant,P=new V(500,400)});missed.Swat(new V(500,400));Check(missed.Corpses.Count==1&&missed.Splats.Count==0,"ant death preserves its existing presentation");for(int n=0;n<140;n++)missed.Spill(new Bug{Id=100+n,Species=Species.Roach,P=new V(500,400)},true);Check(missed.Splats.Count==96&&missed.Splats.All(s=>s.Drops.Count<=64),"liquid memory remains bounded during heavy casualties");missed.StartRound();Check(missed.Splats.Count==0&&missed.Remaining==150,"new round resets the prior battlefield");
  var broom=Empty();broom.Bugs.Add(new Bug{Id=1,Species=Species.Ant,P=new V(400,400)});broom.Corpses.Add(new Bug{Id=2,Species=Species.Roach,P=new V(500,400)});broom.Eggs.Add(new Egg{Id=3,Species=Species.Ant,P=new V(700,400),HatchTime=22});broom.Interactive=true;broom.Tool=Tool.Broom;broom.Press(new V(200,400));broom.Drag(new V(1000,400));broom.Release();Check(broom.Corpses.Count==0&&broom.Eggs.Count==0&&broom.Bugs.Count==1,"fast broom drag cleans full segment while preserving living bugs");
  var drag=Empty();var carry=new Bug{Id=1,Species=Species.Roach,P=new V(500,400)};drag.Bugs.Add(carry);drag.Interactive=true;drag.Tool=Tool.Grab;drag.Press(carry.P);drag.Drag(new V(-100,-100));Check(carry.P.X>=25&&carry.P.Y>=35,"drag clamps the full creature inside work field");drag.Release();Check(drag.Grabbed==null,"release clears held subject");
  var intrude=Empty();intrude.Bugs.Add(new Bug{Id=1,Species=Species.Ant,P=new V(720,135)});intrude.SetRelation(Relation.Truce,"test");Check(intrude.Summon(InvaderKind.Spider),"first foreign invader can enter");intrude.Invaders[0].Cooldown=0;intrude.UpdateInvaders(.05);Check(intrude.Bugs[0].Web>0&&intrude.Bugs[0].Health<10,"spider entangles and damages a real victim");Check(intrude.Invaders[0].Health<95&&intrude.Relation==Relation.Truce,"adult defense does not cancel treaty");Check(!intrude.Summon(InvaderKind.Beetle),"only one living foreign invader at a time");intrude.Invaders[0].Health=0;intrude.Summon(InvaderKind.Beetle);var beetle=intrude.Invaders[^1];beetle.Cooldown=0;intrude.AddFood(beetle.P,Snack.Pizza);original=intrude.Foods[0].Portions;intrude.UpdateInvaders(.05);Check(intrude.Foods[0].Portions==original-24&&beetle.Stolen==24,"beetle raids remove actual food portions");beetle.Age=43;intrude.UpdateInvaders(.05);Check(!intrude.Invaders.Contains(beetle),"surviving foreign raider leaves after encounter");
  var duel=Empty();duel.Bugs.AddRange(new[]{new Bug{Id=1,Species=Species.Ant,P=new V(700,400)},new Bug{Id=2,Species=Species.Roach,P=new V(750,400)}});duel.AddFood(new V(720,400));duel.Combat(.6);Check(duel.Bugs.All(b=>b.Health<10)&&duel.Fights.Count>0,"food dispute creates visible real-damage duel");duel.SetRelation(Relation.Truce,"test");var health=duel.Bugs.Sum(b=>b.Health);duel.Combat(.6);Check(duel.Bugs.Sum(b=>b.Health)==health&&duel.Fights.Count==0,"ceasefire immediately stops inter-camp attacks");
  var trading=Empty();trading.RoachFood=40;trading.AntFood=10;trading.SetRelation(Relation.Trade,"test");trading.Diplomacy(16);Check(trading.RoachFood==36&&trading.AntFood==14,"trade transfers nutrition without creating food");trading.Relation=Relation.Hostile;trading.RelationAge=46;trading.Deaths=6;trading.DeathsAtPeace=0;trading.Diplomacy(.05);Check(trading.Relation==Relation.Truce,"sustained casualties can trigger natural ceasefire");
  var saved=fertile.SaveJson();var restored=new World(fertile.Width,fertile.Height,22);restored.Restore(saved);Check(restored.Bugs.Select(b=>b.Id).SequenceEqual(fertile.Bugs.Select(b=>b.Id))&&restored.Eggs.Count==fertile.Eggs.Count,"save preserves identity and breeding state");Check(restored.Bugs[0].P.Distance(fertile.Bugs[0].P)<.001,"save preserves two-dimensional coordinates");var json=JsonNode.Parse(saved)!;json["Version"]=99;bool rejected=false;try{restored.Restore(json.ToJsonString());}catch(InvalidDataException){rejected=true;}Check(rejected,"unsupported save version rejected");json=JsonNode.Parse(saved)!;json["Bugs"]![0]!["Bulk"]=-1;rejected=false;try{restored.Restore(json.ToJsonString());}catch(InvalidDataException){rejected=true;}Check(rejected,"invalid saved growth rejected");
  restored.Restore(saved);int live=restored.Bugs.Count;restored.Companion();Check(restored.Bugs.Count==live&&!restored.Interactive,"return-to-work preserves colony and disables mouse capture");restored.Resize(1000,700);Check(restored.Bugs.All(b=>double.IsFinite(b.P.X)&&double.IsFinite(b.P.Y)&&b.P.X>=25&&b.P.X<=975&&b.P.Y>=35&&b.P.Y<=665),"display resize keeps creatures within work field");Check(restored.ReportText().Contains("当前关系")&&restored.Reports.Count<=90,"daily report is available with bounded history");
  for(int seed=1;seed<=4;seed++){var sim=new World(1280,800,seed);sim.StartRound();for(int n=0;n<3001;n++)sim.Update(.05);Check(sim.Result&&sim.Remaining==0,"complete autonomous battle seed "+seed);Check(sim.Reserved(Species.Roach)<=60&&sim.Reserved(Species.Ant)<=240,"battle population budget seed "+seed);}
  FeatureTests.Run(Check);EggSprayTests.Run(Check);
  Console.WriteLine(checks+" checks passed");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
